    out=[]
    for row in grid:
        # cyclically move the 3-column compartments one place to the right
        n=len(row)//3
        blocks=[row[3*i:3*i+3] for i in range(n)]
        if n:
            blocks=[blocks[-1]]+blocks[:-1]
        out.append([x for b in blocks for x in b]+row[3*n:])
